test('暂停冻结击退与反馈，恢复后继续，同一穿透箭对每只怪只产生一次伤害', () => {
  const room=new TrainingRoom(arena);
  fireUntilHit(room,'pierce');
  room.setPaused(true);
  const frozen=room.snapshot;
  advance(room,1);
  assert.deepEqual(room.snapshot,frozen);
  room.setPaused(false);
  advance(room,0.14);
  assert.equal(room.snapshot.enemies[0].health,20);
  assert.equal(room.snapshot.hits,1);
  assert.ok(room.snapshot.enemies[0].knockTime<0.000001);
})

test('箭雨每段各产生15点伤害反馈，沿落点向外击退且不合并成虚假大伤害', () => {
  const room=new TrainingRoom({...arena,encounters:[{x:400,y:700,enemies:[{x:680,y:700}]}]});
  room.update({...idle,rain:true,aim:{x:650,y:700}},0);
  advance(room,0.46);
  let state=room.snapshot;
  assert.equal(state.enemies[0].health,45);
  assert.equal(state.effects.find(e=>e.enemy!==undefined).damage,15);
  assert.ok(state.enemies[0].knockX<0);
  assert.ok(state.enemies[0].knockTime>0);
  advance(room,0.36);
  state=room.snapshot;
  assert.equal(state.enemies[0].health,15);
  assert.equal(state.hits,3);
  assert.ok(state.effects.every(e=>e.damage===15));
})

test('靠近残碑按F阅读，长按不反复开关，游戏时间冻结，释放再按关闭且可重读',()=>{
 const r=at({x:840,y:365});
 advance(r,0.2,{...idle,pierce:true});
 const before=r.snapshot;
 assert.equal(before.interaction?.id,'stele');
 press(r);
 assert.equal(r.snapshot.reading,true);assert.equal(r.snapshot.exploration.steleRead,true);
 advance(r,1,{...idle,interact:true,moveX:1,fire:true,rain:true});
 assert.equal(r.snapshot.reading,true);
 assert.deepEqual(r.snapshot.player,before.player);
 assert.deepEqual(r.snapshot.arrows,before.arrows);
 assert.deepEqual(r.snapshot.cooldowns,before.cooldowns);
 press(r);assert.equal(r.snapshot.reading,false);
 press(r);assert.equal(r.snapshot.reading,true);
 r.reset();assert.equal(r.snapshot.reading,true,'阅读暂停中R不能重试');
 r.closeReading();r.reset();assert.equal(r.snapshot.exploration.steleRead,false);
})

